function evidence = f90_xrobo02_extract_candidate_evidence(modelPath, outDir)
%f90_xrobo02_extract_candidate_evidence SLX/XML structure-only evidence entrypoint.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end
taskDir = fileparts(mfilename("fullpath"));
extractor = fullfile(taskDir, "f90_xrobo02_extract_evidence.m");
localRequireBinding(extractor, ...
    "present");
evidence = f90_xrobo02_extract_evidence(modelPath, outDir);
assert(isfield(evidence, "candidate_evidence_ready") && ...
    logical(evidence.candidate_evidence_ready), ...
    "SimuVerity:F90:XROBO02:EvidenceContract", ...
    "Candidate evaluator did not return fresh current evidence.");
assert(isfield(evidence, "score_fields_present") && ...
    ~logical(evidence.score_fields_present), ...
    "SimuVerity:F90:XROBO02:ExtractionOnly", ...
    "Candidate evaluator must not aggregate score fields.");
assert(isfield(evidence, "candidate_binding_preserved_by_current_audit") && ...
    logical(evidence.candidate_binding_preserved_by_current_audit), ...
    "SimuVerity:F90:XROBO02:CandidateBinding", ...
    "The XML structure audit must preserve the sealed candidate binding.");
end

function localRequireBinding(pathValue, expected)
assert(isfile(pathValue) && localFilePresence(pathValue) == lower(string(expected)), ...
    "SimuVerity:F90:XROBO02:DependencyBinding", ...
    "A declared current dependency is missing or changed.");
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

